def _local_media_discovery_call_allowed(tool_name: str, command: str) -> bool:
    """Allow harmless workspace discovery before media evidence is acquired.

    The local-media evidence gate must prevent answering from a filename and
    must block content-reading or mutating side channels. It should not turn
    a benign directory listing into a failed recovery path: models commonly
    inspect the workspace first and select ``inspect_media`` on the next turn.
    Keep shell support deliberately narrow and side-effect free.
    """
    name = str(tool_name or "").strip().lower()
    if name in {"ls", "glob", "get_workspace"}:
        return True
    if name != "bash":
        return False
    text = str(command or "").strip()
    # ``#!bg`` is a parser marker emitted in some fenced shell blocks.
    text = re.sub(r"^#!\s*bg\s*\n?", "", text, count=1).strip()
    if not text or "\n" in text:
        return False
    if re.search(r"[;&|<>`$()]", text):
        return False
    return bool(re.fullmatch(r"(?:ls|stat|file)(?:\s+-[A-Za-z0-9./_-]+)*\s+[^\s]+", text))


def _resolved_tool_call_id(
    native_call: Optional[Mapping[str, Any]],
    *,
    session_id: str,
    round_num: int,
    tool_index: int,
    tool_name: str,
) -> str:
    """Return one stable SSE correlation ID for every executed tool call.

    Native model calls already carry an ID and must retain it. Harness-generated
    follow-through calls (artifact verification, recovery, and deterministic
    routing) do not, but downstream trace consumers still need matching
    ``tool_start`` and ``tool_output`` identities.
    """

    native_id = str((native_call or {}).get("id") or "").strip()
    if native_id:
        return native_id
    seed = f"{session_id}\0{round_num}\0{tool_index}\0{tool_name}"
    digest = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:24]
    return f"odysseus-auto-{digest}"

logger = logging.getLogger(__name__)

_MODEL_TOOL_SURFACES = {"none", "compact", "full"}
_ROUTE_THINKING_MODES = {"auto", "on", "off"}
_NO_THINKING_COMPACT_DOMAINS = {
    "email",
    "notes_calendar_tasks",
    "memory",
    "contacts",
    "documents",
}


def _normalize_model_tool_surface(value: Any) -> str:
    value = str(value or "").strip().lower()
    return value if value in _MODEL_TOOL_SURFACES else ""


def _route_thinking_policy() -> str:
    mode = os.getenv("ODYSSEUS_QWEN_ROUTE_THINKING", "auto").strip().lower()
    return mode if mode in _ROUTE_THINKING_MODES else "auto"


def _thinking_mode_for_route(
    *,
    model: str,
    tool_surface: str,
    domains: Set[str],
    direct: bool = False,
) -> Optional[str]:
    """Select Qwen thinking mode for the current agent route.

    ``auto`` keeps thinking available for broad/search/coding routes but turns
    it off for compact personal-tool surfaces where we want direct tool calls
    and concise final answers.  Teacher/data-generation runs can set
    ``ODYSSEUS_QWEN_ROUTE_THINKING=on``; production can force ``off``.
    """

    model_name = str(model or "").lower()
    qwen35_family = bool(re.search(r"(?:qwen3\.5|qwen35)", model_name))
    if not (_is_qwen38_tool_router(model) or qwen35_family):
        return None
    # The pre-Heretic control is served by vLLM without a verified reasoning
    # parser.  If thinking is enabled, its private analysis is returned as
    # ordinary content and the WebUI buffers a long pre-answer transcript.
    if is_odysseus_merged_tools_model(model_name):
        return "off"
    policy = _route_thinking_policy()
    if policy in {"on", "off"}:
        return policy
    if tool_surface == "compact" and (set(domains or set()) & _NO_THINKING_COMPACT_DOMAINS):
        return "off"
    if direct and "qwen35-email" in model_name:
        return "off"
    return None


def _qwen_tool_router_output_budget(requested: int | None) -> int:
    """Keep an explicit agent budget; default only when none was requested."""

    try:
        value = int(requested or 0)
    except (TypeError, ValueError):
        value = 0
    return value if value > 0 else 1024


def _allow_visual_tool_evidence_for_model(model: str) -> bool:
    """Keep pixels for multimodal Odysseus routers; legacy routers stay text-only."""

    return is_odysseus_merged_tools_model(model) or not _is_qwen38_tool_router(model)


def _malformed_native_tool_recovery_instruction(names: Set[str]) -> str:
    """Return targeted, schema-level recovery for dropped native calls."""

    if "write_file" in set(names or ()):
        return (
            "Your previous write_file call was incomplete or malformed. Call "
            "write_file once with both path and content. Keep the file within "
            "the output budget by using loops, reusable functions, CSS, or data "
            "arrays instead of repeating generated markup. Do not restate the plan."
        )
    return ""


def _looks_like_explicit_web_search_request(
    text: str,
    *,
    local_media_turn: bool = False,
) -> bool:
    """Recognize explicit public-web intent without hijacking local media work."""

    if local_media_turn:
        return False
    value = str(text or "")
    return bool(
        re.search(
            r"\b(?:latest|current|today|online|internet|web|search|look\s+up)\b"
            r"|\bfind\b.{0,80}\b(?:official\s+)?(?:website|site|page|url|link)\b",
            value,
            re.IGNORECASE,
        )
        and not re.search(
            r"\b(?:email|mail|inbox|calendar|meeting|task|note|memory|saved\s+research|"
            r"skills?|procedures?|documents?|docs?|past\s+chat|prior\s+chat|"
            r"previous\s+conversation|research|deep\s+dive|investigate)\b",
            value,
            re.IGNORECASE,
        )
    )


def _repeated_artifact_mutation_can_finish(
    names: Sequence[str],
    *,
    html_verified: bool,
) -> bool:
    """Stop after a verified artifact is regenerated byte-for-byte."""

    normalized = {str(name or "").strip().lower() for name in names}
    return bool(
        html_verified
        and normalized
        and normalized <= {"write_file", "edit_file", "apply_patch"}
    )


def _malformed_write_needs_body_handoff(
    names: Set[str],
    missing_artifacts: Sequence[str],
    *,
    attempts: int,
) -> bool:
    """Use raw-body recovery once instead of repeating truncated tool JSON."""

    missing = [str(path or "").strip() for path in missing_artifacts]
    return bool(
        attempts == 0
        and "write_file" in set(names or ())
        and len(missing) == 1
        and missing[0]
        and not _binary_artifact_path(missing[0])
    )


def _post_finish_inspection_should_converge(
    *,
    finish_nudge_sent: bool,
    correction_seen: bool,
    force_answer: bool,
    verification_only: bool,
    current_inspection: bool,
    can_complete: bool,
) -> bool:
    """Bound repeated inspection after a completed artifact's finish nudge."""

    return bool(
        finish_nudge_sent
        and not correction_seen
        and not force_answer
        and verification_only
        and current_inspection
        and can_complete
    )


def _parse_model_tool_modes(raw: Any) -> Dict[str, str]:
    if not raw:
        return {}
    try:
        data = json.loads(raw) if isinstance(raw, str) else raw
    except Exception:
        return {}
    if not isinstance(data, dict):
        return {}
    modes: Dict[str, str] = {}
    for key, value in data.items():
        model_id = str(key or "").strip()
        mode = _normalize_model_tool_surface(value)
        if model_id and mode:
            modes[model_id] = mode
    return modes


def _model_id_tokens(value: Any) -> List[str]:
    leaf = os.path.basename(str(value or "").strip().rstrip("/")).lower()
    return [part for part in re.split(r"[^a-z0-9]+", leaf) if part]


def _model_tool_mode_for_model(modes: Dict[str, str], model: str) -> str:
    """Resolve a per-model tool mode across exact ids and runtime aliases."""

    model = str(model or "").strip()
    if not model or not modes:
        return ""
    exact = modes.get(model)
    if exact:
        return exact
    lowered = model.lower()
    for key, mode in modes.items():
        if str(key or "").strip().lower() == lowered:
            return mode

    requested_tokens = _model_id_tokens(model)
    if not requested_tokens:
        return ""
    matches: List[str] = []
    for key, mode in modes.items():
        configured_tokens = _model_id_tokens(key)
        if not configured_tokens:
            continue
        if configured_tokens == requested_tokens:
            matches.append(mode)
        elif (
            len(requested_tokens) >= 2
            and len(configured_tokens) > len(requested_tokens)
            and configured_tokens[: len(requested_tokens)] == requested_tokens
        ):
            matches.append(mode)
    return matches[0] if len(matches) == 1 else ""


def _apply_tool_surface_to_schemas(
    schemas: List[Dict[str, Any]],
    surface: str,
) -> List[Dict[str, Any]]:
    surface = _normalize_model_tool_surface(surface)
    if surface == "none":
        return []
    if surface == "compact":
        return [_compact_openai_tool_schema(schema) for schema in (schemas or [])]
    return list(schemas or [])


def _contract_allows_early_completion(contract) -> bool:
    # A shortcut cannot prove it completed every action, including multiple
    # actions within one family. Let the normal loop handle contract work.
    if contract is None:
        return True
    active = getattr(contract, "active_capabilities", None)
    if active is not None:
        return not active and not contract.required
    return not (contract.capabilities or contract.required or contract.offered)


def _contract_prompt_domains(contract) -> Set[str]:
    """Adapt the resolved capabilities to legacy prompt-domain vocabulary."""
    aliases = {
        "notes": "notes_calendar_tasks", "calendar": "notes_calendar_tasks",
        "tasks": "notes_calendar_tasks", "search_browser": "web",
        "shell_files": "files", "cookbook_admin": "cookbook",
    }
    return {aliases.get(family, family) for family in contract.capabilities}


def _contract_allows_single_action_terminal(contract) -> bool:
    return contract is None or len(contract.capabilities) <= 1


def _request_has_compound_actions(text: str) -> bool:
    """Return whether a turn explicitly requests multiple semantic operations."""
    value = str(text or "")
    if (
        len(re.findall(r"\bhttps?://[^\s<>\"']+", value, re.IGNORECASE)) >= 2
        and re.search(
            r"\b(?:compare|contrast|synthesi[sz]e|cite|citing|evidence)\b",
            value,
            re.IGNORECASE,
        )
    ):
        return True
    groups = (
        r"\b(?:create|add|make|write|draft|schedule|book|set\s+up)\b",
        r"\b(?:list|search|find|locate|look\s+up)\b",
        r"\b(?:read|open|inspect|view|download)\b",
        r"\b(?:edit|update|change|replace|rewrite|append)\b",
        r"\b(?:suggest|recommend|propose)\b",
        r"\b(?:pause|disable|suspend)\b",
        r"\b(?:resume|re-enable|bring\s+(?:it|them)\s+back)\b",
        r"\b(?:delete|remove|cancel|get\s+rid\s+of)\b",
        r"\b(?:verify|confirm|check)\b",
    )
    return sum(bool(re.search(pattern, value, re.IGNORECASE)) for pattern in groups) >= 2


def _request_forbids_execution_retry(text: str) -> bool:
    """Return whether the user explicitly bounded command execution to one try."""
    value = str(text or "")
    return bool(
        re.search(
            r"\b(?:do\s+not|don['’]?t|dont|never)\s+"
            r"(?:retry|re-?run|run\s+(?:it|that|the\s+command)\s+again)\b",
            value,
            re.IGNORECASE,
        )
        or re.search(
            r"\b(?:run|execute|try)\b[^.!?\n]{0,120}\b(?:once|one\s+time)\b",
            value,
            re.IGNORECASE,
        )
    )


def _contract_mutation_signature(block, contract):
    """Deduplicate an exact successful mutation for the rest of this turn.

    A model may continue after a successful write in order to verify or summarize
    it.  That continuation must never execute the same state-changing call again,
    regardless of whether the turn contract names one capability or several.
    """
    from src.tool_capabilities import ToolEffect, capabilities_for_action
    effects = capabilities_for_action(block.tool_type, block.content).effects
    if not effects & {ToolEffect.WRITE_PRIVATE, ToolEffect.WRITE_WORKSPACE,
                      ToolEffect.EXTERNAL_SIDE_EFFECT, ToolEffect.ADMIN_CHANGE,
                      ToolEffect.DESTRUCTIVE}:
        return None
    content = block.content or ""
    try:
        content = json.dumps(json.loads(content), sort_keys=True, separators=(",", ":"))
    except (TypeError, ValueError):
        pass
    return block.tool_type, content


def _has_accepted_contract_tool_call(contract, tool_blocks) -> bool:
    """Accepted calls own their arguments; intent recovery only fills a gap."""
    return contract is not None and any(
        contract.permits(block.tool_type) for block in (tool_blocks or ())
    )


def _required_safe_read_operation(contract):
    """Consume the optional operation without expanding permissions or scope."""
    operation = getattr(contract, "required_operation", None)
    if operation is None:
        operation = getattr(contract, "required_read_operation", None)
    active = getattr(contract, "active_capabilities", None)
    operation_scope = active if active else getattr(contract, "capabilities", ())
    if operation is None or len(operation_scope) > 1:
        return None
    def field(name, default=None):
        return operation.get(name, default) if isinstance(operation, Mapping) else getattr(operation, name, default)
    name, args, limit = field("tool_name", field("tool")), field("args"), field("max_items")
    # Email account metadata is safe; mailbox contents and mutations stay out.
    # Deliberately exclude web/search and shell/files.
    supported = {
        "manage_notes", "manage_calendar", "manage_tasks", "manage_documents",
        "manage_memory", "manage_skills", "list_models", "list_cookbook_servers",
        "list_cached_models", "list_served_models", "list_serve_presets", "list_downloads",
        "list_email_accounts", "mcp__email__list_email_accounts",
    }
    if name not in supported or not isinstance(args, Mapping) or not contract.permits(name):
        return None
    if limit is not None and (type(limit) is not int or limit < 0):
        return None
    try:
        content = json.dumps(dict(args), sort_keys=True, ensure_ascii=False, allow_nan=False)
    except (TypeError, ValueError):
        return None
    from src.tool_capabilities import ToolEffect
    capability = capabilities_for_action(name, content)
    if not capability.known or capability.effects != frozenset({ToolEffect.READ_PRIVATE}):
        return None
    return ToolBlock(name, content), limit


def _required_read_native_id(block, native_calls):
    """Keep the native ID only when the model supplied the immutable operation."""
    expected = json.loads(block.content)
    def canonical_name(name):
        return "list_email_accounts" if name == "mcp__email__list_email_accounts" else name
    for call in native_calls or ():
        function = call.get("function") or call
        if canonical_name(function.get("name")) != canonical_name(block.tool_type):
            continue
        args = function.get("arguments")
        try:
            args = json.loads(args) if isinstance(args, str) else args
        except (TypeError, ValueError):
            continue
        if args == expected:
            return call.get("id")
    return None


def _required_read_summary(block, result, max_items=None):
    raw = next((result.get(key) for key in ("output", "response", "results", "content")
                if result.get(key)), "")
    if not isinstance(raw, str):
        raw = json.dumps(raw, ensure_ascii=False, default=str)
    raw = _strip_think_blocks(strip_tool_blocks(raw)).removeprefix("AI: ").strip()
    if max_items == 0:
        return "Read completed; no items displayed."
    args = json.loads(block.content)
    action = str(args.get("action") or "").lower()
    summary = ""
    bounded_helpers = {
        "manage_notes": _note_list_summary_from_tool_output,
        "manage_calendar": _calendar_list_summary_from_tool_output,
        "manage_documents": _document_list_summary_from_tool_output,
        "manage_skills": _skills_list_summary_from_tool_output,
    }
    if max_items is not None and action in {"list", "list_events", "index", "search", "find", "lis"}:
        helper = bounded_helpers.get(block.tool_type)
        if helper:
            summary = helper(raw, max_items=max_items)
    if not summary:
        summary = _ody_qwen_terminal_tool_summary({
            "tool": block.tool_type, "command": block.content, "output": raw,
        }) or raw
    if max_items is not None:
        # Existing renderers embed overflow items in expandable HTML comments.
        # A contract cap bounds the actual answer payload, including overflow.
        summary = summary.split("<!-- ody-more-", 1)[0].rstrip()
        lines = summary.splitlines()
        rows = [i for i, line in enumerate(lines) if re.match(r"^\s*(?:[-*]|\d+[.)])\s+", line)]
        if len(rows) > max_items:
            summary = "\n".join(lines[:rows[max_items]]).rstrip()
    return summary or "Read completed; no content was returned."


async def _dispatch_required_safe_read(operation, **execution_context):
    """Use the normal permission/security dispatcher; success alone owns output."""
    block, max_items = operation
    desc, result = await execute_tool_block(block, **execution_context)
    answer = _required_read_summary(block, result, max_items) if tool_result_is_successful(result) else ""
    return desc, result, answer


def _tool_rejection_reason(tool_name, policy_names, tool_policy, contract=None):
    if contract is not None and not contract.permits(tool_name):
        offered = sorted(
            name for name in (contract.offered or ())
            if name not in {"ask_user", "update_plan"}
        )
        available = (
            f" Available tool{'s' if len(offered) != 1 else ''} for this turn: "
            + ", ".join(offered)
            + "."
            if offered else ""
        )
        return (
            f"Tool '{tool_name}' is outside the requested turn capabilities."
            f"{available}"
        )
    if tool_policy is not None:
        blocked_name = next((name for name in policy_names if tool_policy.blocks(name)), None)
        if blocked_name is not None:
            return tool_policy.reason_for(blocked_name)
    return f"Tool '{tool_name}' is disabled by the current request policy."


