def _canonical_native_tool_name_for_offered(
    name: str,
    offered_tool_names: Optional[Set[str]],
) -> str:
    """Map recognized native aliases onto a tool actually offered this turn."""

    value = str(name or "").strip()
    if not value or not offered_tool_names or value in offered_tool_names:
        return value
    mapped = _NATIVE_EMAIL_ALIAS_TO_MCP.get(value)
    if mapped and mapped in offered_tool_names:
        return mapped
    mapped = _NATIVE_TOOL_ALIASES.get(value)
    if mapped and mapped in offered_tool_names:
        return mapped
    return value


def _native_tool_name_was_accepted(name: str, accepted_names: Set[str]) -> bool:
    """Match native and namespaced spellings of the same executed tool.

    Resolution may intentionally convert a short public name such as
    ``list_emails`` to its MCP transport name.  Routing telemetry should not
    report that successful conversion as a rejected request.
    """
    requested = str(name or "").strip()
    if not requested:
        return False
    if requested in accepted_names:
        return True
    requested_leaf = requested.removeprefix("mcp__").split("__")[-1]
    return any(
        accepted.removeprefix("mcp__").split("__")[-1] == requested_leaf
        for accepted in accepted_names
    )


def _normalize_native_alias_arguments(
    original_name: str,
    canonical_name: str,
    arguments: Any,
) -> Any:
    """Preserve alias intent while adapting it to the canonical schema."""
    if canonical_name != "private_browser" or original_name not in _NATIVE_TOOL_ALIASES:
        return arguments
    try:
        args = json.loads(arguments) if isinstance(arguments, str) else arguments
    except (TypeError, json.JSONDecodeError):
        return arguments
    if not isinstance(args, dict):
        return arguments
    normalized = dict(args)
    normalized.setdefault("action", "open")
    if not normalized.get("url") and normalized.get("path"):
        normalized["url"] = normalized.pop("path")
    return json.dumps(normalized, ensure_ascii=False)


def _redirect_local_html_inspection_call(
    name: str,
    arguments: Any,
    offered_tool_names: Optional[Set[str]],
) -> tuple[str, Any]:
    """Route a local HTML inspection through the rendered-page capability."""
    if name != "inspect_media" or "private_browser" not in set(offered_tool_names or ()):
        return name, arguments
    try:
        args = json.loads(arguments) if isinstance(arguments, str) else arguments
    except (TypeError, json.JSONDecodeError):
        return name, arguments
    if not isinstance(args, dict):
        return name, arguments
    path = str(args.get("path") or "").strip()
    if not re.search(r"(?:^/workspace/|^file:/).*\.html?$", path, re.IGNORECASE):
        return name, arguments
    url = path if path.lower().startswith("file:") else f"file://{path}"
    return "private_browser", json.dumps(
        {"action": "open", "url": url},
        ensure_ascii=False,
    )


def _drop_legacy_email_alias_schemas_when_mcp_available(
    schemas: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """Prefer one canonical email function surface in native tool calls."""

    names = {
        (schema.get("function") or {}).get("name") or schema.get("name")
        for schema in (schemas or [])
        if isinstance(schema, dict)
    }
    if not any(str(name or "").startswith("mcp__email__") for name in names):
        return list(schemas or [])
    return [
        schema for schema in (schemas or [])
        if ((schema.get("function") or {}).get("name") or schema.get("name"))
        not in _LEGACY_NATIVE_EMAIL_ALIASES
    ]


