_WORKSPACE_PREFIX_RE = re.compile(r"/workspace/", re.IGNORECASE)
_WORKSPACE_SCRIPT_RE = re.compile(
    r"/workspace/[^\s`\"']+\.(?:py|pyw|sh|bash|js|mjs|ts|rb|pl)\b",
    re.IGNORECASE,
)
_WORKSPACE_QUOTED_TOKEN_TAIL_RE = re.compile(r"[^\s`\"']*")
_HTTP_PREFIX_RE = re.compile(r"https?://", re.IGNORECASE)
_PDF_URL_RE = re.compile(r"https?://\S+(?:\.pdf\b|/pdf/)", re.IGNORECASE)
_NONSPACE_TOKEN_TAIL_RE = re.compile(r"\S*")


def _mentions_workspace_script(text: str) -> bool:
    return has_prefixed_token_match(
        str(text or ""),
        _WORKSPACE_PREFIX_RE,
        _WORKSPACE_SCRIPT_RE,
        _WORKSPACE_QUOTED_TOKEN_TAIL_RE,
    )


def _mentions_pdf_url(text: str) -> bool:
    return has_prefixed_token_match(
        str(text or ""), _HTTP_PREFIX_RE, _PDF_URL_RE, _NONSPACE_TOKEN_TAIL_RE
    )


def _blocked_network_recovery_tools(events: Sequence[Dict[str, Any]]) -> Set[str]:
    """Preserve native recovery tools named by our own network guard.

    Compact routing is recomputed after every tool result. When the native
    shell/Python guard rejects ad-hoc HTTP it deliberately tells the model to
    use bounded web/PDF tools instead. Dropping those schemas on the next
    round makes that recovery impossible. Match only the harness-authored
    guard prefix on tool-role results so user or fetched content cannot widen
    the tool surface.
    """
    for event in reversed(list(events or [])[-6:]):
        if not isinstance(event, dict):
            continue
        candidates: list[str] = []
        if (
            (event.get("type") == "tool_output" or isinstance(event.get("tool"), str))
            and isinstance(event.get("output"), str)
        ):
            candidates.append(event["output"])
        elif event.get("role") == "tool" and isinstance(event.get("content"), str):
            candidates.append(event["content"])
        elif event.get("role") == "user" and isinstance(event.get("content"), list):
            for part in event["content"]:
                if not isinstance(part, dict) or part.get("type") != "tool_result":
                    continue
                result = part.get("content")
                if isinstance(result, str):
                    candidates.append(result)
                elif isinstance(result, list):
                    candidates.extend(
                        item.get("text", "") for item in result
                        if isinstance(item, dict) and item.get("type") == "text"
                    )
        for content in candidates:
            if re.match(
                r"^(?:bash|python): ad-hoc HTTP (?:downloads are|access is) disabled "
                r"when native web tools are available\.",
                content.strip(),
            ):
                return {"pdf_extract", "web_fetch", "web_search"}
    return set()


def _compact_native_route_tools(
    tool_names: Optional[Set[str]],
    text: str,
    domains: Set[str],
) -> Optional[Set[str]]:
    """Keep compact native schemas capable but bounded.

    The normal tool selector intentionally over-includes safety rails and
    adjacent tools. That is reasonable for large hosted models, but compact
    local models pay for every native schema in prompt tokens. Compact mode
    keeps a small general agent kit plus the narrow domain tools implied by
    the current turn.
    """

    if tool_names is None:
        return None
    original = set(tool_names)
    if not original:
        return original

    q = str(text or "").lower()
    workspace_artifact_request = bool(
        any(
            not path.startswith("/workspace/fixtures/")
            for path in _explicit_workspace_files(text)
        )
        and re.search(
            r"(?:\b(?:create|generate|save|write|render|export|produce|build|make)\b|"
            r"创建|生成|保存|写入|写在|输出|放进|制作|截取|剪辑|拼接|导出)",
            text,
            re.IGNORECASE,
        )
    )
    _workspace_paths = _explicit_workspace_files(text)
    workspace_generator_request = bool(
        workspace_artifact_request
        and (
            _mentions_workspace_script(text)
            or (
                # A multi-output data+visual deliverable is an execution
                # workflow even when its generator is discovered after the
                # source document is fetched. Keep the shell floor for this
                # generic artifact shape, but not for simple summaries.
                len(_workspace_paths) >= 2
                and any(Path(path).suffix.casefold() in {".csv", ".json", ".xlsx"} for path in _workspace_paths)
                and any(Path(path).suffix.casefold() in {".png", ".jpg", ".jpeg", ".svg", ".pdf"} for path in _workspace_paths)
            )
        )
    )
    compact: Set[str] = set(original & _COMPACT_AGENT_CORE_TOOLS)

    if "web" in domains:
        compact.update(WEB_TOOL_NAMES)
        if (
            "pdf_extract" in original
            and _mentions_pdf_url(text)
        ):
            compact.add("pdf_extract")
        if _looks_like_youtube_tool_turn(text):
            compact.add("youtube_tool")

    named_online_document = bool(re.search(
        r"https?://|\bPDFs?\b|\b(?:paper|report|study)\b[\s\S]{0,240}"
        r"\b(?:table|benchmark|extract|scores?|metrics?)\b",
        text,
        re.IGNORECASE,
    ))
    if named_online_document:
        compact.update(original & {"web_search", "web_fetch", "pdf_extract"})
        # A local artifact task may mention a report/table/study while still
        # requiring execution of an existing workspace script.  Keep the
        # shell mutation capability for that case; only suppress it for an
        # actually URL-backed document route.
        if not workspace_generator_request:
            compact.discard("bash")

    # A compact model still needs the native multimodal reader when the user
    # names a local image/video. Local media can be misclassified as a web
    # domain (especially in non-English prompts); do not replace its inspector
    # with browser/search schemas that cannot access workspace bytes.
    if _explicit_local_media_inputs(text):
        local_pdf_input = any(
            Path(path).suffix.casefold() == ".pdf"
            for path in _explicit_local_media_inputs(text)
        )
        compact.update(original & {
            "inspect_media", "extract_text", "transcribe_media", "bash", "read_file", "ls",
            "pdf_extract" if local_pdf_input else "__no_local_pdf__",
        })
        if (
            local_pdf_input
            and any(
                not path.startswith("/workspace/fixtures/")
                for path in _explicit_workspace_files(text)
            )
            and re.search(
                r"(?:\b(?:create|generate|save|write|render|export|produce|build|make)\b|"
                r"创建|生成|保存|写入|写在|输出|放进|制作|截取|剪辑|拼接|导出)",
                text,
                re.IGNORECASE,
            )
        ):
            compact.discard("bash")
        _browser_render = _local_media_needs_browser_render(text)
        if _browser_render:
            # Rendering is a concrete capability requirement. Do not require
            # semantic retrieval to have selected the browser first; the final
            # schema/security filters still decide whether it is executable.
            compact.add("private_browser")
        if (
            not re.search(r"https?://", text, re.IGNORECASE)
            and not _local_media_needs_web_lookup(text)
        ):
            _irrelevant_local_media_web_tools = set(WEB_TOOL_NAMES) | {
                "youtube_tool"
            }
            if not local_pdf_input:
                _irrelevant_local_media_web_tools.add("pdf_extract")
            if not _browser_render:
                _irrelevant_local_media_web_tools.add("private_browser")
            compact.difference_update(_irrelevant_local_media_web_tools)

    # Artifact creation is a capability requirement, even when multilingual
    # intent classification labels an HTML deliverable as only ``web``.
    # Preserve the bounded native writer surface selected by the outer router.
    if (
        any(
            not path.startswith("/workspace/fixtures/")
            for path in _explicit_workspace_files(text)
        )
        and re.search(
            r"(?:\b(?:create|generate|save|write|render|export|produce|build|make)\b|"
            r"创建|生成|保存|写入|写在|输出|放进|制作|截取|剪辑|拼接|导出)",
            text,
            re.IGNORECASE,
        )
    ):
        # Artifact completion is an execution contract.  The semantic RAG
        # result can contain only media readers (as happened for a video ->
        # output.txt task), so do not require the generic writer to have been
        # retrieved before exposing the native mutation capability.
        compact.update({"python", "write_file", "read_file", "ls", "grep", "glob"})
        # The compact reducer starts from a deliberately tiny core and would
        # otherwise drop the browser that the outer artifact floor selected.
        # HTML is a rendered deliverable: keep native browser verification in
        # the actual schema set, not only in the routing metadata.
        if any(
            Path(path).suffix.casefold() in {".html", ".htm"}
            for path in _explicit_workspace_files(text)
        ):
            # An HTML deliverable needs a render/inspection loop even when the
            # compact semantic route retrieved only file writers.
            compact.add("private_browser")

    if "files" in domains:
        compact.update(original & _DOMAIN_TOOL_MAP["files"])

    if "documents" in domains:
        compact.update(original & _DOMAIN_TOOL_MAP["documents"])

    if "notes_calendar_tasks" in domains:
        compact.update(original & _DOMAIN_TOOL_MAP["notes_calendar_tasks"])

    # The semantic selector and compact reducer must agree on explicit
    # multilingual state-management concepts. The classifier can label a
    # cross-domain request only as email even though retrieval correctly kept
    # manage_tasks; rebuilding solely from that domain would then discard the
    # only executable task manager. Reuse the shared literal registry rather
    # than maintaining a second language list here.
    from src.tool_index import NON_LATIN_LITERAL_TOOL_HINTS
    for tool, phrases in NON_LATIN_LITERAL_TOOL_HINTS.items():
        if tool in original and any(phrase in text for phrase in phrases):
            compact.add(tool)

    if "memory" in domains or re.search(r"\b(?:remember|memory|memories)\b", q):
        compact.add("manage_memory")

    if "skills" in domains or re.search(r"\b(?:skill|skills|tdd|skill library)\b", q):
        compact.add("manage_skills")

    if "ui" in domains:
        compact.add("ui_control")

    if "sessions" in domains:
        compact.update(original & _DOMAIN_TOOL_MAP["sessions"])

    if re.search(r"\b(?:ask_teacher|chat_with_model)\b", q):
        compact.update(original & {"ask_teacher", "chat_with_model", "list_models"})

    explicit_cookbook_request = bool(re.search(
        r"\b(?:serve|download|load|stop|host)\s+(?:a\s+|the\s+)?(?:model|checkpoint)\b"
        r"|\b(?:model\s+endpoint|served\s+model|vllm|ollama|hugging\s*face)\b",
        q,
    ))
    if "cookbook" in domains and (
        not workspace_artifact_request or explicit_cookbook_request
    ):
        compact.update(original & {
            "list_served_models",
            "list_downloads",
            "list_cached_models",
            "list_cookbook_servers",
            "list_serve_presets",
            "serve_model",
            "serve_preset",
            "stop_served_model",
            "adopt_served_model",
        })

    explicit_email_request = bool(
        re.search(
            r"\b(?:e-?mail|emails|mailbox|inbox|attachment|attachments|newsletter|"
            r"mailing\s+list|sender|senders|spam|phishing|junk)\b"
            r"|(?:邮件|收件箱|发件箱|草稿|附件|发件人|垃圾邮件|钓鱼邮件)",
            q,
        )
    )
    emailish = explicit_email_request or (
        "email" in domains and not workspace_artifact_request
    )
    if emailish:
        # A personal-email request should not inherit the whole general agent
        # kit. File reads remain useful for request-scoped attachments and
        # cross-source workflows, while shell/code/search schemas distract
        # compact models unless another detected domain explicitly needs them.
        if "web" not in domains and not re.search(r"https?://", q):
            compact.difference_update({"web_search", "web_fetch"})
        if "files" not in domains and not workspace_artifact_request:
            compact.difference_update({"bash", "python", "grep", "glob"})
        compact.update(_COMPACT_EMAIL_READ_TOOLS)
        if re.search(r"\b(?:search|find|look\s+for)\b|(?:搜索|查找)", q):
            compact.add("search_emails")
        if re.search(r"\battachments?\b|附件", q):
            compact.add("download_attachment")
        reply_intent = bool(re.search(r"\b(?:reply|respond|response)\b|(?:回复|回信)", q))
        draft_intent = bool(re.search(r"\b(?:draft|write|compose)\b|(?:草稿|撰写|写邮件)", q))
        send_intent = bool(re.search(r"\b(?:send|tell\s+them)\b|(?:发送|发邮件|通知)", q))
        if reply_intent or draft_intent or send_intent:
            compact.add("resolve_contact")
        if reply_intent:
            compact.add("draft_email_reply")
            if not draft_intent:
                compact.add("reply_to_email")
        if draft_intent:
            compact.add("draft_email")
        if send_intent:
            compact.add("send_email")
        if re.search(
            r"\b(?:archive|delete|trash|remove|mark|read|unread|favorite|unfavorite|done|undone|unarchive)\b"
            r"|(?:归档|删除|移除|标记已读|标记未读|收藏|取消收藏)",
            q,
        ):
            compact.update(_COMPACT_EMAIL_ACTION_TOOLS)
        if re.search(r"\b(?:spam|phishing|junk|block|blocked|suspicious)\b|(?:垃圾邮件|钓鱼邮件|拦截|可疑)", q):
            compact.update(_COMPACT_EMAIL_SPAM_TOOLS)
        if re.search(r"\b(?:unsubscribe|newsletter|mailing list)\b|(?:退订|取消订阅|邮件列表)", q):
            compact.update(_COMPACT_EMAIL_UNSUBSCRIBE_TOOLS)

    if "contacts" in domains or re.search(r"\b(?:contact|contacts|phone|address book)\b", q):
        compact.update(original & _DOMAIN_TOOL_MAP["contacts"])

    # File operations and workspace discovery form one capability bundle.
    # Semantic retrieval often finds a concrete reader without also returning
    # its orientation tool, while compact models commonly discover the active
    # root before choosing paths.  Keep that dependency available whenever a
    # native workspace file tool survives compaction.
    if compact & _WORKSPACE_FILE_TOOLS:
        compact.add("get_workspace")

    compact.update(original & {"ask_user", "update_plan", "host_shell"})
    if named_online_document:
        compact.difference_update({"bash", "host_shell"})
    # Keep the artifact mutation floor even when semantic RAG did not retrieve
    # those names.  This must happen after the final compact allowlist too;
    # otherwise the writer added above is silently removed before schema build.
    _artifact_mutation_tools = (
        {
            "python", "write_file", "read_file", "ls", "grep", "glob",
            # A declared media deliverable may require a real transformation
            # (for example ffmpeg extraction/concat).  Keep the native shell
            # mutation capability even when compact semantic retrieval only
            # returned media readers.  This is a capability floor, not a
            # task-specific tool injection.
            *( {"bash"}
               if workspace_generator_request or (
                   _explicit_local_media_inputs(text)
                   and not any(
                       Path(path).suffix.casefold() == ".pdf"
                       for path in _explicit_local_media_inputs(text)
                   )
               )
               else set() ),
        }
        if any(
            not path.startswith("/workspace/fixtures/")
            for path in _explicit_workspace_files(text)
        )
        and re.search(
            r"(?:\b(?:create|generate|save|write|render|export|produce|build|make)\b|"
            r"创建|生成|保存|写入|写在|输出|放进|制作|截取|剪辑|拼接|导出)",
            text,
            re.IGNORECASE,
        )
        else set()
    )
    if (
        any(
            not path.startswith("/workspace/fixtures/")
            for path in _explicit_workspace_files(text)
        )
        and re.search(
            r"(?:\b(?:create|generate|save|write|render|export|produce|build|make)\b|"
            r"创建|生成|保存|写入|写在|输出|放进|制作|截取|剪辑|拼接|导出)",
            text,
            re.IGNORECASE,
        )
        and workspace_generator_request
    ):
        _artifact_mutation_tools.add("bash")
    compact &= (
        original
        | _COMPACT_AGENT_CORE_TOOLS
        | _PRIVATE_WEB_TOOL_NAMES
        | {"get_workspace"}
    )
    compact.update(_artifact_mutation_tools)
    return compact or original


def _compact_native_artifact_tools(
    tool_names: Set[str],
    *,
    text: str,
    artifacts: Sequence[str],
    media_inputs: Sequence[str],
) -> Set[str]:
    """Narrow a compact native route to a complete artifact capability bundle.

    Explicit create/generate deliverables do not need project-navigation and
    patch-management tools merely because they live in a workspace.  Preserve
    acquisition, creation, inspection, and verification capabilities while
    removing unrelated coding-agent schemas that distract compact models.
    """
    original = set(tool_names or set())
    if not artifacts:
        return original

    value = str(text or "")
    artifact_suffixes = {Path(path).suffix.casefold() for path in artifacts}
    media_suffixes = {Path(path).suffix.casefold() for path in media_inputs}
    allowed = {
        "ask_user", "update_plan", "read_file", "write_file", "python", "ls",
        "inspect_media", "generate_image", "edit_image",
    }
    if artifact_suffixes & {".html", ".htm"}:
        allowed.add("private_browser")
    # The declared deliverable may be only a PNG/JPEG even though producing
    # it requires rendering an HTML intermediate.  In that contract the
    # prompt, not the output suffix, carries the browser requirement.  Keep
    # the native browser without widening the open-web tool surface.
    if _local_media_needs_browser_render(value):
        allowed.add("private_browser")
    if media_suffixes & {
        ".mp3", ".wav", ".m4a", ".aac", ".flac", ".ogg", ".opus",
        ".mp4", ".mov", ".mkv", ".webm", ".avi",
    }:
        allowed.add("transcribe_media")
    if media_suffixes & {".pdf"}:
        allowed.add("pdf_extract")
    if not media_inputs:
        # A non-media artifact may depend on source acquisition selected by
        # RAG or forced by the caller even when the user did not paste a URL
        # into the current turn (for example, "research sources and create a
        # report"). Preserve those bounded readers; local-media reproduction
        # routes can safely discard them unless external lookup is explicit.
        allowed.update(original & (set(WEB_TOOL_NAMES) | {"web_fetch", "pdf_extract"}))
    if _local_media_needs_web_lookup(value) or re.search(r"https?://", value, re.IGNORECASE):
        allowed.update(WEB_TOOL_NAMES)
        allowed.update({"web_fetch", "pdf_extract"})
    if (
        _mentions_workspace_script(value)
        or (
            len(artifacts) >= 2
            and artifact_suffixes & {".csv", ".json", ".xlsx"}
            and artifact_suffixes & {".png", ".jpg", ".jpeg", ".svg", ".pdf"}
        )
    ):
        allowed.update({"bash", "manage_bg_jobs"})
    if re.search(r"\b(?:edit|modify|patch|fix|repair|update|change)\b", value, re.IGNORECASE):
        allowed.update({"edit_file", "apply_patch", "grep", "glob"})

    compact = original & allowed
    # A route must never lose every mutation mechanism due to an upstream
    # retrieval miss. Prefer the native writer when it is available.
    if "write_file" in original:
        compact.add("write_file")
    return compact or original


def _compact_native_media_analysis_tools(
    tool_names: Set[str],
    *,
    text: str,
    media_inputs: Sequence[str],
) -> Set[str]:
    """Remove coding-agent noise from read-only native media analysis."""
    original = set(tool_names or set())
    if not media_inputs:
        return original
    suffixes = {Path(path).suffix.casefold() for path in media_inputs}
    allowed = {"inspect_media", "extract_text", "transcribe_media", "read_file", "ls", "python"}
    if suffixes & {
        ".mp4", ".mov", ".mkv", ".webm", ".avi", ".mp3", ".wav",
        ".m4a", ".aac", ".flac", ".ogg", ".opus",
    }:
        allowed.add("bash")
    if ".pdf" in suffixes:
        allowed.add("pdf_extract")
    if _visual_text_extraction_requested(text):
        # OCR is a complete, purpose-built read surface.  Do not expose
        # generic Python or the visual-description tool alongside it: models
        # otherwise improvise long Tesseract/crop loops after the native OCR
        # result instead of returning the requested exact text.
        if "extract_text" in original:
            return {"extract_text"}
        allowed.discard("transcribe_media")
    if _local_media_needs_web_lookup(text) or re.search(r"https?://", text, re.IGNORECASE):
        allowed.update(WEB_TOOL_NAMES)
    if _local_media_needs_browser_render(text):
        allowed.add("private_browser")
    return original & allowed


def _compact_native_artifact_schemas(
    schemas: Sequence[Dict[str, Any]],
    *,
    text: str,
    artifacts: Sequence[str],
    media_inputs: Sequence[str],
    preserved_names: Optional[Set[str]] = None,
) -> list[Dict[str, Any]]:
    """Apply artifact routing policy at the final native-schema boundary.

    Several routing layers contribute tools before a request is sent. A later
    layer must not silently reintroduce network or coding schemas that the
    compact artifact policy removed. Caller-declared environment tools remain
    an explicit contract and are therefore preserved.
    """
    items = list(schemas or [])
    names = {
        schema.get("function", {}).get("name") or schema.get("name")
        for schema in items
    }
    allowed = _compact_native_artifact_tools(
        {name for name in names if name},
        text=text,
        artifacts=artifacts,
        media_inputs=media_inputs,
    ) | set(preserved_names or set())
    filtered = [
        schema for schema in items
        if (schema.get("function", {}).get("name") or schema.get("name")) in allowed
    ]
    return [
        _specialize_inspect_media_schema(schema, media_inputs)
        if (schema.get("function", {}).get("name") or schema.get("name"))
        == "inspect_media"
        else schema
        for schema in filtered
    ]


def _specialize_inspect_media_schema(
    schema: Dict[str, Any],
    media_inputs: Sequence[str],
) -> Dict[str, Any]:
    """Hide media-mode arguments that cannot apply to known local inputs."""
    suffixes = {
        Path(str(path or "")).suffix.casefold()
        for path in media_inputs
        if Path(str(path or "")).suffix
    }
    raster = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp", ".tif", ".tiff"}
    if suffixes and suffixes <= raster:
        keep = {"path", "max_dimension", "query", "crop"}
        description = "Inspect a local still image with the current multimodal model."
    elif suffixes and suffixes <= {".svg"}:
        keep = {"path", "max_dimension", "query", "crop", "output_path"}
        description = (
            "Inspect a local SVG with the current multimodal model; provide a "
            "workspace .png output_path when a raster render is needed."
        )
    elif suffixes and suffixes <= {".pdf"}:
        keep = {"path", "max_dimension", "query", "page", "pages"}
        description = "Render and inspect local PDF pages with the current multimodal model."
    elif suffixes and suffixes <= {".mp4", ".webm", ".mov", ".mkv", ".m4v", ".avi"}:
        keep = {
            "path", "start", "end", "duration", "frames", "sampling",
            "max_dimension", "query", "timestamp", "output_path", "speed",
            "segments", "exports", "caption", "crop", "timestamp_path",
        }
        description = (
            "Inspect or export local video frames and ranges with the current "
            "multimodal model."
        )
    else:
        return schema

    specialized = json.loads(json.dumps(schema))
    function = specialized.get("function", {})
    function["description"] = description
    parameters = function.get("parameters", {})
    properties = parameters.get("properties", {})
    parameters["properties"] = {
        name: value for name, value in properties.items() if name in keep
    }
    parameters["required"] = ["path"]
    return specialized


def _web_only_route_tools(text: str, disabled_tools: Set[str]) -> Set[str]:
    tools = set(WEB_TOOL_NAMES) | {"ask_user", "update_plan"}
    if _looks_like_youtube_tool_turn(text) and "youtube_tool" not in set(disabled_tools or set()):
        tools.add("youtube_tool")
    if (
        (
            _looks_like_explicit_browser_interaction(text)
            or _looks_like_map_browser_request(text)
        )
        and "private_browser" not in set(disabled_tools or set())
    ):
        tools.add("private_browser")
    return tools

_WORKSPACE_AGENT_TOOLS = (
    _DOMAIN_TOOL_MAP["files"]
    | {"manage_skills", "ask_teacher", "web_search", "web_fetch", "ask_user", "update_plan"}
)
_BACKEND_LOCAL_COMPUTER_TOOLS = {
    "bash",
    "python",
    "read_file",
    "write_file",
    "edit_file",
    "apply_patch",
    "grep",
    "glob",
    "ls",
    "get_workspace",
    "manage_bg_jobs",
}


_SFT_WORKSPACE_DISABLED_ENV = "ODYSSEUS_SFT_DISABLE_WORKSPACE_TOOLS"
_SFT_DISABLED_WORKSPACE_TOOLS = (
    (set(_WORKSPACE_AGENT_TOOLS) | set(_BACKEND_LOCAL_COMPUTER_TOOLS))
    - set(WEB_TOOL_NAMES)
    # Skills are a private backend registry, not a filesystem/workspace tool.
    # Keep it available in synthetic SFT sessions so a retrieval miss cannot
    # turn an explicit skill request into a context-only answer.
    - {"ask_user", "update_plan", "manage_skills", "ask_teacher", "bash"}
)


def _workspace_tools_disabled_for_owner(owner: Optional[str]) -> bool:
    """Keep synthetic personal-assistant fixtures out of TUI workspace mode."""
    flag = os.getenv(_SFT_WORKSPACE_DISABLED_ENV, "1").strip().lower()
    if flag in {"0", "false", "no", "off"}:
        return False
    return str(owner or "").strip().startswith("sft_")


def _workspace_tools_disabled_for_request(
    owner: Optional[str],
    client_runtime_context: Optional[Dict[str, Any]],
) -> bool:
    """Keep SFT web sessions isolated without disabling declared native workspaces."""
    native_terminal = bool(
        isinstance(client_runtime_context, dict)
        and client_runtime_context.get("surface") == "odysseus-native"
        and client_runtime_context.get("terminal_agent") is True
    )
    return _workspace_tools_disabled_for_owner(owner) and not native_terminal


def _strip_workspace_tools_for_sft(
    tool_names: Optional[Set[str]],
    owner: Optional[str],
    client_runtime_context: Optional[Dict[str, Any]] = None,
) -> Optional[Set[str]]:
    native_terminal = bool(
        isinstance(client_runtime_context, dict)
        and client_runtime_context.get("surface") == "odysseus-native"
        and client_runtime_context.get("terminal_agent") is True
    )
    if (
        tool_names is None
        or native_terminal
        or not _workspace_tools_disabled_for_owner(owner)
    ):
        return tool_names
    return set(tool_names) - _SFT_DISABLED_WORKSPACE_TOOLS


def _domain_rules_for_tools(tool_names: set) -> list[str]:
    names = set(tool_names or set())
    rules = []
    for domain, domain_tools in _DOMAIN_TOOL_MAP.items():
        if names & domain_tools:
            rules.append(_DOMAIN_RULES[domain])
    if names & {"create_session", "list_sessions", "manage_session", "manage_documents", "manage_notes", "manage_calendar", "manage_tasks", "manage_skills", "manage_research"}:
        rules.append(_LINK_RULES)
    return rules

